{
    /** @return array{subject:string,body:string}|null */
    public static function template(string $scenario, string $locale): ?array
    {
        $data = self::data($locale);
        $map = [
            'booking_created_customer' => ['created_customer_subject', 'created_customer_body'],
            'booking_created_admin' => ['created_admin_subject', 'created_admin_body'],
            'booking_cancelled_customer' => ['cancelled_customer_subject', 'cancelled_customer_body'],
            'booking_cancelled_admin' => ['cancelled_admin_subject', 'cancelled_admin_body'],
            'booking_completed_customer' => ['completed_customer_subject', 'completed_customer_body'],
            'booking_completed_admin' => ['completed_admin_subject', 'completed_admin_body'],
        ];
        if (!isset($map[$scenario])) { return null; }
        [$subject, $body] = $map[$scenario];
        return ['subject' => str_replace('\\n', "\n", $data[$subject]), 'body' => str_replace('\\n', "\n", $data[$body])];
    }

    public static function notice(string $locale, string $recipientType): string
    {
        $data = self::data($locale);
        return str_replace('\\n', "\n", $data[$recipientType === 'admin' ? 'notice_admin' : 'notice_customer']);
    }

