            'de_DE' => ['created_customer_subject' => 'Wir haben Ihre Anfrage #{booking_id} erhalten', 'created_customer_body' => 'Hallo {customer_name},\n\nwir haben Ihre Anfrage für „{package_title}“ erhalten. Wir kontaktieren Sie, um Details, Datum und Uhrzeit abzustimmen.\n\nAnfragenummer: #{booking_id}\n\nAnfrage stornieren: {cancellation_url}', 'created_admin_subject' => 'Neue Buchungsanfrage #{booking_id}', 'created_admin_body' => 'Eine neue Buchungsanfrage ist eingegangen.\n\nKunde: {customer_name}\nE-Mail: {customer_email}\nTelefon: {customer_phone}\nLeistung: {package_title}\nAnfragenummer: #{booking_id}\n\nKontaktieren Sie den Kunden, um die Details abzustimmen.', 'cancelled_customer_subject' => 'Anfrage #{booking_id} storniert', 'cancelled_customer_body' => 'Hallo {customer_name},\n\nIhre Anfrage für „{package_title}“ wurde storniert.\n\nAnfragenummer: #{booking_id}', 'cancelled_admin_subject' => 'Anfrage #{booking_id} storniert', 'cancelled_admin_body' => 'Die Anfrage #{booking_id} für „{package_title}“ wurde storniert.\n\nKunde: {customer_name}\nE-Mail: {customer_email}', 'completed_customer_subject' => 'Anfrage #{booking_id} abgeschlossen', 'completed_customer_body' => 'Hallo {customer_name},\n\nIhre Anfrage für „{package_title}“ wurde als abgeschlossen markiert.\n\nAnfragenummer: #{booking_id}\n\nVielen Dank, dass Sie sich für uns entschieden haben.', 'completed_admin_subject' => 'Anfrage #{booking_id} abgeschlossen', 'completed_admin_body' => 'Die Anfrage #{booking_id} für „{package_title}“ wurde als abgeschlossen markiert.\n\nKunde: {customer_name}', 'notice_customer' => 'Datum und Uhrzeit der Veranstaltung werden separat vereinbart. Wir kontaktieren Sie in Kürze per E-Mail oder Telefon, falls eine Telefonnummer angegeben wurde.', 'notice_admin' => 'Es wurde kein Veranstaltungsdatum und keine Uhrzeit ausgewählt. Kontaktieren Sie den Kunden per E-Mail oder Telefon, falls eine Telefonnummer angegeben wurde.'],
            'ru_RU' => ['created_customer_subject' => 'Мы получили вашу заявку #{booking_id}', 'created_customer_body' => 'Здравствуйте, {customer_name}!\n\nМы получили вашу заявку на «{package_title}». Мы свяжемся с вами, чтобы согласовать детали, дату и время.\n\nНомер заявки: #{booking_id}\n\nОтменить заявку: {cancellation_url}', 'created_admin_subject' => 'Новая заявка на бронирование #{booking_id}', 'created_admin_body' => 'Получена новая заявка на бронирование.\n\nКлиент: {customer_name}\nEmail: {customer_email}\nТелефон: {customer_phone}\nУслуга: {package_title}\nНомер заявки: #{booking_id}\n\nСвяжитесь с клиентом, чтобы согласовать детали.', 'cancelled_customer_subject' => 'Заявка #{booking_id} отменена', 'cancelled_customer_body' => 'Здравствуйте, {customer_name}!\n\nВаша заявка на «{package_title}» отменена.\n\nНомер заявки: #{booking_id}', 'cancelled_admin_subject' => 'Заявка #{booking_id} отменена', 'cancelled_admin_body' => 'Заявка #{booking_id} на «{package_title}» отменена.\n\nКлиент: {customer_name}\nEmail: {customer_email}', 'completed_customer_subject' => 'Заявка #{booking_id} завершена', 'completed_customer_body' => 'Здравствуйте, {customer_name}!\n\nВаша заявка на «{package_title}» отмечена как завершённая.\n\nНомер заявки: #{booking_id}\n\nСпасибо, что выбрали нас.', 'completed_admin_subject' => 'Заявка #{booking_id} завершена', 'completed_admin_body' => 'Заявка #{booking_id} на «{package_title}» отмечена как завершённая.\n\nКлиент: {customer_name}', 'notice_customer' => 'Дата и время мероприятия будут согласованы отдельно. Мы скоро свяжемся с вами по электронной почте или телефону, если номер был указан.', 'notice_admin' => 'Дата и время мероприятия не выбраны. Свяжитесь с клиентом по электронной почте или телефону, если номер был указан.'],
            'et' => ['created_customer_subject' => 'Saime teie taotluse #{booking_id}', 'created_customer_body' => 'Tere {customer_name}!\n\nSaime teie taotluse paketile „{package_title}”. Võtame teiega ühendust, et leppida kokku üksikasjad, kuupäev ja kellaaeg.\n\nTaotluse number: #{booking_id}\n\nTühista taotlus: {cancellation_url}', 'created_admin_subject' => 'Uus broneerimistaotlus #{booking_id}', 'created_admin_body' => 'Saabus uus broneerimistaotlus.\n\nKlient: {customer_name}\nE-post: {customer_email}\nTelefon: {customer_phone}\nTeenus: {package_title}\nTaotluse number: #{booking_id}\n\nVõtke kliendiga ühendust, et üksikasjad kokku leppida.', 'cancelled_customer_subject' => 'Taotlus #{booking_id} tühistati', 'cancelled_customer_body' => 'Tere {customer_name}!\n\nTeie taotlus paketile „{package_title}” tühistati.\n\nTaotluse number: #{booking_id}', 'cancelled_admin_subject' => 'Taotlus #{booking_id} tühistati', 'cancelled_admin_body' => 'Taotlus #{booking_id} paketile „{package_title}” tühistati.\n\nKlient: {customer_name}\nE-post: {customer_email}', 'completed_customer_subject' => 'Taotlus #{booking_id} lõpetatud', 'completed_customer_body' => 'Tere {customer_name}!\n\nTeie taotlus paketile „{package_title}” märgiti lõpetatuks.\n\nTaotluse number: #{booking_id}\n\nTäname, et valisite meid.', 'completed_admin_subject' => 'Taotlus #{booking_id} lõpetatud', 'completed_admin_body' => 'Taotlus #{booking_id} paketile „{package_title}” märgiti lõpetatuks.\n\nKlient: {customer_name}', 'notice_customer' => 'Sündmuse kuupäev ja kellaaeg lepitakse eraldi kokku. Võtame teiega peagi ühendust e-posti või telefoni teel, kui telefoninumber oli lisatud.', 'notice_admin' => 'Sündmuse kuupäeva ja kellaaega ei valitud. Võtke kliendiga ühendust e-posti või telefoni teel, kui telefoninumber oli lisatud.'],
            'es_ES' => ['created_customer_subject' => 'Hemos recibido su solicitud #{booking_id}', 'created_customer_body' => 'Hola {customer_name},\n\nHemos recibido su solicitud para “{package_title}”. Nos pondremos en contacto para acordar los detalles, la fecha y la hora.\n\nNúmero de solicitud: #{booking_id}\n\nCancelar solicitud: {cancellation_url}', 'created_admin_subject' => 'Nueva solicitud de reserva #{booking_id}', 'created_admin_body' => 'Se ha recibido una nueva solicitud de reserva.\n\nCliente: {customer_name}\nCorreo electrónico: {customer_email}\nTeléfono: {customer_phone}\nServicio: {package_title}\nNúmero de solicitud: #{booking_id}\n\nContacte con el cliente para acordar los detalles.', 'cancelled_customer_subject' => 'Solicitud cancelada #{booking_id}', 'cancelled_customer_body' => 'Hola {customer_name},\n\nSu solicitud para “{package_title}” ha sido cancelada.\n\nNúmero de solicitud: #{booking_id}', 'cancelled_admin_subject' => 'Solicitud cancelada #{booking_id}', 'cancelled_admin_body' => '#{booking_id} — “{package_title}”: ha sido cancelada.\n\nCliente: {customer_name}\nCorreo electrónico: {customer_email}', 'completed_customer_subject' => 'Solicitud completada #{booking_id}', 'completed_customer_body' => 'Hola {customer_name},\n\nSu solicitud para “{package_title}” ha sido marcada como completada.\n\nNúmero de solicitud: #{booking_id}\n\nGracias por elegirnos.', 'completed_admin_subject' => 'Solicitud completada #{booking_id}', 'completed_admin_body' => '#{booking_id} — “{package_title}”: ha sido marcada como completada.\n\nCliente: {customer_name}', 'notice_customer' => 'La fecha y la hora del evento se acordarán por separado. Nos pondremos en contacto pronto por correo electrónico o teléfono si se facilitó un número.', 'notice_admin' => 'No se seleccionó fecha ni hora. Contacte con el cliente por correo electrónico o teléfono si se facilitó un número.'],
            'fr_FR' => ['created_customer_subject' => 'Nous avons reçu votre demande #{booking_id}', 'created_customer_body' => 'Bonjour {customer_name},\n\nNous avons reçu votre demande pour “{package_title}”. Nous vous contacterons afin de convenir des détails, de la date et de l’heure.\n\nNuméro de demande: #{booking_id}\n\nAnnuler la demande: {cancellation_url}', 'created_admin_subject' => 'Nouvelle demande de réservation #{booking_id}', 'created_admin_body' => 'Une nouvelle demande de réservation a été reçue.\n\nClient: {customer_name}\nE-mail: {customer_email}\nTéléphone: {customer_phone}\nPrestation: {package_title}\nNuméro de demande: #{booking_id}\n\nContactez le client pour convenir des détails.', 'cancelled_customer_subject' => 'Demande annulée #{booking_id}', 'cancelled_customer_body' => 'Bonjour {customer_name},\n\nVotre demande pour “{package_title}” a été annulée.\n\nNuméro de demande: #{booking_id}', 'cancelled_admin_subject' => 'Demande annulée #{booking_id}', 'cancelled_admin_body' => '#{booking_id} — “{package_title}”: a été annulée.\n\nClient: {customer_name}\nE-mail: {customer_email}', 'completed_customer_subject' => 'Demande terminée #{booking_id}', 'completed_customer_body' => 'Bonjour {customer_name},\n\nVotre demande pour “{package_title}” a été marquée comme terminée.\n\nNuméro de demande: #{booking_id}\n\nMerci de nous avoir choisis.', 'completed_admin_subject' => 'Demande terminée #{booking_id}', 'completed_admin_body' => '#{booking_id} — “{package_title}”: a été marquée comme terminée.\n\nClient: {customer_name}', 'notice_customer' => 'La date et l’heure seront convenues séparément. Nous vous contacterons prochainement par e-mail ou téléphone si un numéro a été fourni.', 'notice_admin' => 'Aucune date ni heure n’a été sélectionnée. Contactez le client par e-mail ou téléphone si un numéro a été fourni.'],
            'it_IT' => ['created_customer_subject' => 'Abbiamo ricevuto la tua richiesta #{booking_id}', 'created_customer_body' => 'Ciao {customer_name},\n\nAbbiamo ricevuto la tua richiesta per “{package_title}”. Ti contatteremo per concordare dettagli, data e ora.\n\nNumero richiesta: #{booking_id}\n\nAnnulla richiesta: {cancellation_url}', 'created_admin_subject' => 'Nuova richiesta di prenotazione #{booking_id}', 'created_admin_body' => 'È stata ricevuta una nuova richiesta di prenotazione.\n\nCliente: {customer_name}\nEmail: {customer_email}\nTelefono: {customer_phone}\nServizio: {package_title}\nNumero richiesta: #{booking_id}\n\nContatta il cliente per concordare i dettagli.', 'cancelled_customer_subject' => 'Richiesta annullata #{booking_id}', 'cancelled_customer_body' => 'Ciao {customer_name},\n\nLa tua richiesta per “{package_title}” è stata annullata.\n\nNumero richiesta: #{booking_id}', 'cancelled_admin_subject' => 'Richiesta annullata #{booking_id}', 'cancelled_admin_body' => '#{booking_id} — “{package_title}”: è stata annullata.\n\nCliente: {customer_name}\nEmail: {customer_email}', 'completed_customer_subject' => 'Richiesta completata #{booking_id}', 'completed_customer_body' => 'Ciao {customer_name},\n\nLa tua richiesta per “{package_title}” è stata contrassegnata come completata.\n\nNumero richiesta: #{booking_id}\n\nGrazie per averci scelto.', 'completed_admin_subject' => 'Richiesta completata #{booking_id}', 'completed_admin_body' => '#{booking_id} — “{package_title}”: è stata contrassegnata come completata.\n\nCliente: {customer_name}', 'notice_customer' => 'La data e l’ora saranno concordate separatamente. Ti contatteremo presto via email o telefono se è stato fornito un numero.', 'notice_admin' => 'Non sono state selezionate data o ora. Contatta il cliente via email o telefono se è stato fornito un numero.'],
            'pt_PT' => ['created_customer_subject' => 'Recebemos o seu pedido #{booking_id}', 'created_customer_body' => 'Olá {customer_name},\n\nRecebemos o seu pedido para “{package_title}”. Entraremos em contacto para combinar os detalhes, a data e a hora.\n\nNúmero do pedido: #{booking_id}\n\nCancelar pedido: {cancellation_url}', 'created_admin_subject' => 'Novo pedido de reserva #{booking_id}', 'created_admin_body' => 'Foi recebido um novo pedido de reserva.\n\nCliente: {customer_name}\nE-mail: {customer_email}\nTelefone: {customer_phone}\nServiço: {package_title}\nNúmero do pedido: #{booking_id}\n\nContacte o cliente para combinar os detalhes.', 'cancelled_customer_subject' => 'Pedido cancelado #{booking_id}', 'cancelled_customer_body' => 'Olá {customer_name},\n\nO seu pedido para “{package_title}” foi cancelado.\n\nNúmero do pedido: #{booking_id}', 'cancelled_admin_subject' => 'Pedido cancelado #{booking_id}', 'cancelled_admin_body' => '#{booking_id} — “{package_title}”: foi cancelado.\n\nCliente: {customer_name}\nE-mail: {customer_email}', 'completed_customer_subject' => 'Pedido concluído #{booking_id}', 'completed_customer_body' => 'Olá {customer_name},\n\nO seu pedido para “{package_title}” foi marcado como concluído.\n\nNúmero do pedido: #{booking_id}\n\nObrigado por nos escolher.', 'completed_admin_subject' => 'Pedido concluído #{booking_id}', 'completed_admin_body' => '#{booking_id} — “{package_title}”: foi marcado como concluído.\n\nCliente: {customer_name}', 'notice_customer' => 'A data e a hora serão combinadas separadamente. Entraremos em contacto em breve por e-mail ou telefone, caso tenha sido indicado um número.', 'notice_admin' => 'Não foi selecionada uma data nem uma hora. Contacte o cliente por e-mail ou telefone, caso tenha sido indicado um número.'],
            'pt_BR' => ['created_customer_subject' => 'Recebemos sua solicitação #{booking_id}', 'created_customer_body' => 'Olá {customer_name},\n\nRecebemos sua solicitação para “{package_title}”. Entraremos em contato para combinar os detalhes, a data e o horário.\n\nNúmero da solicitação: #{booking_id}\n\nCancelar solicitação: {cancellation_url}', 'created_admin_subject' => 'Nova solicitação de reserva #{booking_id}', 'created_admin_body' => 'Uma nova solicitação de reserva foi recebida.\n\nCliente: {customer_name}\nE-mail: {customer_email}\nTelefone: {customer_phone}\nServiço: {package_title}\nNúmero da solicitação: #{booking_id}\n\nEntre em contato com o cliente para combinar os detalhes.', 'cancelled_customer_subject' => 'Solicitação cancelada #{booking_id}', 'cancelled_customer_body' => 'Olá {customer_name},\n\nSua solicitação para “{package_title}” foi cancelada.\n\nNúmero da solicitação: #{booking_id}', 'cancelled_admin_subject' => 'Solicitação cancelada #{booking_id}', 'cancelled_admin_body' => '#{booking_id} — “{package_title}”: foi cancelada.\n\nCliente: {customer_name}\nE-mail: {customer_email}', 'completed_customer_subject' => 'Solicitação concluída #{booking_id}', 'completed_customer_body' => 'Olá {customer_name},\n\nSua solicitação para “{package_title}” foi marcada como concluída.\n\nNúmero da solicitação: #{booking_id}\n\nObrigado por nos escolher.', 'completed_admin_subject' => 'Solicitação concluída #{booking_id}', 'completed_admin_body' => '#{booking_id} — “{package_title}”: foi marcada como concluída.\n\nCliente: {customer_name}', 'notice_customer' => 'A data e o horário serão combinados separadamente. Entraremos em contato em breve por e-mail ou telefone, caso um número tenha sido informado.', 'notice_admin' => 'Nenhuma data ou horário foi selecionado. Entre em contato com o cliente por e-mail ou telefone, caso um número tenha sido informado.'],
            'nl_NL' => ['created_customer_subject' => 'We hebben uw aanvraag ontvangen #{booking_id}', 'created_customer_body' => 'Hallo {customer_name},\n\nWe hebben uw aanvraag ontvangen voor “{package_title}”. We nemen contact op om de details, datum en tijd af te spreken.\n\nAanvraagnummer: #{booking_id}\n\nAanvraag annuleren: {cancellation_url}', 'created_admin_subject' => 'Nieuwe boekingsaanvraag #{booking_id}', 'created_admin_body' => 'Er is een nieuwe boekingsaanvraag ontvangen.\n\nKlant: {customer_name}\nE-mail: {customer_email}\nTelefoon: {customer_phone}\nDienst: {package_title}\nAanvraagnummer: #{booking_id}\n\nNeem contact op met de klant om de details af te spreken.', 'cancelled_customer_subject' => 'Aanvraag geannuleerd #{booking_id}', 'cancelled_customer_body' => 'Hallo {customer_name},\n\nUw aanvraag voor “{package_title}” is geannuleerd.\n\nAanvraagnummer: #{booking_id}', 'cancelled_admin_subject' => 'Aanvraag geannuleerd #{booking_id}', 'cancelled_admin_body' => '#{booking_id} — “{package_title}”: is geannuleerd.\n\nKlant: {customer_name}\nE-mail: {customer_email}', 'completed_customer_subject' => 'Aanvraag voltooid #{booking_id}', 'completed_customer_body' => 'Hallo {customer_name},\n\nUw aanvraag voor “{package_title}” is als voltooid gemarkeerd.\n\nAanvraagnummer: #{booking_id}\n\nBedankt dat u voor ons hebt gekozen.', 'completed_admin_subject' => 'Aanvraag voltooid #{booking_id}', 'completed_admin_body' => '#{booking_id} — “{package_title}”: is als voltooid gemarkeerd.\n\nKlant: {customer_name}', 'notice_customer' => 'De datum en tijd worden apart afgesproken. We nemen binnenkort contact op via e-mail of telefoon als een nummer is opgegeven.', 'notice_admin' => 'Er is geen datum of tijd geselecteerd. Neem contact op met de klant via e-mail of telefoon als een nummer is opgegeven.'],
            'pl_PL' => ['created_customer_subject' => 'Otrzymaliśmy Twoje zgłoszenie #{booking_id}', 'created_customer_body' => 'Dzień dobry {customer_name},\n\nOtrzymaliśmy Twoje zgłoszenie dotyczące “{package_title}”. Skontaktujemy się, aby ustalić szczegóły, datę i godzinę.\n\nNumer zgłoszenia: #{booking_id}\n\nAnuluj zgłoszenie: {cancellation_url}', 'created_admin_subject' => 'Nowe zgłoszenie rezerwacji #{booking_id}', 'created_admin_body' => 'Otrzymano nowe zgłoszenie rezerwacji.\n\nKlient: {customer_name}\nE-mail: {customer_email}\nTelefon: {customer_phone}\nUsługa: {package_title}\nNumer zgłoszenia: #{booking_id}\n\nSkontaktuj się z klientem, aby ustalić szczegóły.', 'cancelled_customer_subject' => 'Zgłoszenie anulowane #{booking_id}', 'cancelled_customer_body' => 'Dzień dobry {customer_name},\n\nTwoje zgłoszenie dotyczące “{package_title}” zostało anulowane.\n\nNumer zgłoszenia: #{booking_id}', 'cancelled_admin_subject' => 'Zgłoszenie anulowane #{booking_id}', 'cancelled_admin_body' => '#{booking_id} — “{package_title}”: zostało anulowane.\n\nKlient: {customer_name}\nE-mail: {customer_email}', 'completed_customer_subject' => 'Zgłoszenie zakończone #{booking_id}', 'completed_customer_body' => 'Dzień dobry {customer_name},\n\nTwoje zgłoszenie dotyczące “{package_title}” zostało oznaczone jako zakończone.\n\nNumer zgłoszenia: #{booking_id}\n\nDziękujemy za wybranie naszej oferty.', 'completed_admin_subject' => 'Zgłoszenie zakończone #{booking_id}', 'completed_admin_body' => '#{booking_id} — “{package_title}”: zostało oznaczone jako zakończone.\n\nKlient: {customer_name}', 'notice_customer' => 'Data i godzina zostaną ustalone osobno. Wkrótce skontaktujemy się e-mailem lub telefonicznie, jeśli podano numer.', 'notice_admin' => 'Nie wybrano daty ani godziny. Skontaktuj się z klientem e-mailem lub telefonicznie, jeśli podano numer.'],
            'cs_CZ' => ['created_customer_subject' => 'Obdrželi jsme vaši žádost #{booking_id}', 'created_customer_body' => 'Dobrý den {customer_name},\n\nObdrželi jsme vaši žádost o “{package_title}”. Budeme vás kontaktovat, abychom dohodli podrobnosti, datum a čas.\n\nČíslo žádosti: #{booking_id}\n\nZrušit žádost: {cancellation_url}', 'created_admin_subject' => 'Nová žádost o rezervaci #{booking_id}', 'created_admin_body' => 'Byla přijata nová žádost o rezervaci.\n\nZákazník: {customer_name}\nE-mail: {customer_email}\nTelefon: {customer_phone}\nSlužba: {package_title}\nČíslo žádosti: #{booking_id}\n\nKontaktujte zákazníka a dohodněte podrobnosti.', 'cancelled_customer_subject' => 'Žádost zrušena #{booking_id}', 'cancelled_customer_body' => 'Dobrý den {customer_name},\n\nVaše žádost o “{package_title}” byla zrušena.\n\nČíslo žádosti: #{booking_id}', 'cancelled_admin_subject' => 'Žádost zrušena #{booking_id}', 'cancelled_admin_body' => '#{booking_id} — “{package_title}”: byla zrušena.\n\nZákazník: {customer_name}\nE-mail: {customer_email}', 'completed_customer_subject' => 'Žádost dokončena #{booking_id}', 'completed_customer_body' => 'Dobrý den {customer_name},\n\nVaše žádost o “{package_title}” byla označena jako dokončená.\n\nČíslo žádosti: #{booking_id}\n\nDěkujeme, že jste si vybrali nás.', 'completed_admin_subject' => 'Žádost dokončena #{booking_id}', 'completed_admin_body' => '#{booking_id} — “{package_title}”: byla označena jako dokončená.\n\nZákazník: {customer_name}', 'notice_customer' => 'Datum a čas budou dohodnuty samostatně. Brzy vás kontaktujeme e-mailem nebo telefonicky, pokud bylo uvedeno číslo.', 'notice_admin' => 'Nebylo vybráno datum ani čas. Kontaktujte zákazníka e-mailem nebo telefonicky, pokud bylo uvedeno číslo.'],
            'sk_SK' => ['created_customer_subject' => 'Prijali sme vašu žiadosť #{booking_id}', 'created_customer_body' => 'Dobrý deň {customer_name},\n\nPrijali sme vašu žiadosť o “{package_title}”. Budeme vás kontaktovať, aby sme dohodli podrobnosti, dátum a čas.\n\nČíslo žiadosti: #{booking_id}\n\nZrušiť žiadosť: {cancellation_url}', 'created_admin_subject' => 'Nová žiadosť o rezerváciu #{booking_id}', 'created_admin_body' => 'Bola prijatá nová žiadosť o rezerváciu.\n\nZákazník: {customer_name}\nE-mail: {customer_email}\nTelefón: {customer_phone}\nSlužba: {package_title}\nČíslo žiadosti: #{booking_id}\n\nKontaktujte zákazníka a dohodnite podrobnosti.', 'cancelled_customer_subject' => 'Žiadosť zrušená #{booking_id}', 'cancelled_customer_body' => 'Dobrý deň {customer_name},\n\nVaša žiadosť o “{package_title}” bola zrušená.\n\nČíslo žiadosti: #{booking_id}', 'cancelled_admin_subject' => 'Žiadosť zrušená #{booking_id}', 'cancelled_admin_body' => '#{booking_id} — “{package_title}”: bola zrušená.\n\nZákazník: {customer_name}\nE-mail: {customer_email}', 'completed_customer_subject' => 'Žiadosť dokončená #{booking_id}', 'completed_customer_body' => 'Dobrý deň {customer_name},\n\nVaša žiadosť o “{package_title}” bola označená ako dokončená.\n\nČíslo žiadosti: #{booking_id}\n\nĎakujeme, že ste si vybrali nás.', 'completed_admin_subject' => 'Žiadosť dokončená #{booking_id}', 'completed_admin_body' => '#{booking_id} — “{package_title}”: bola označená ako dokončená.\n\nZákazník: {customer_name}', 'notice_customer' => 'Dátum a čas budú dohodnuté samostatne. Čoskoro vás kontaktujeme e-mailom alebo telefonicky, ak bolo uvedené číslo.', 'notice_admin' => 'Nebol vybraný dátum ani čas. Kontaktujte zákazníka e-mailom alebo telefonicky, ak bolo uvedené číslo.'],
            'sl_SI' => ['created_customer_subject' => 'Prejeli smo vašo zahtevo #{booking_id}', 'created_customer_body' => 'Pozdravljeni {customer_name},\n\nPrejeli smo vašo zahtevo za “{package_title}”. Kontaktirali vas bomo, da se dogovorimo o podrobnostih, datumu in času.\n\nŠtevilka zahteve: #{booking_id}\n\nPrekliči zahtevo: {cancellation_url}', 'created_admin_subject' => 'Nova zahteva za rezervacijo #{booking_id}', 'created_admin_body' => 'Prejeta je bila nova zahteva za rezervacijo.\n\nStranka: {customer_name}\nE-pošta: {customer_email}\nTelefon: {customer_phone}\nStoritev: {package_title}\nŠtevilka zahteve: #{booking_id}\n\nObrnite se na stranko in se dogovorite o podrobnostih.', 'cancelled_customer_subject' => 'Zahteva preklicana #{booking_id}', 'cancelled_customer_body' => 'Pozdravljeni {customer_name},\n\nVaša zahteva za “{package_title}” je bila preklicana.\n\nŠtevilka zahteve: #{booking_id}', 'cancelled_admin_subject' => 'Zahteva preklicana #{booking_id}', 'cancelled_admin_body' => '#{booking_id} — “{package_title}”: je bila preklicana.\n\nStranka: {customer_name}\nE-pošta: {customer_email}', 'completed_customer_subject' => 'Zahteva zaključena #{booking_id}', 'completed_customer_body' => 'Pozdravljeni {customer_name},\n\nVaša zahteva za “{package_title}” je bila označena kot zaključena.\n\nŠtevilka zahteve: #{booking_id}\n\nHvala, ker ste izbrali nas.', 'completed_admin_subject' => 'Zahteva zaključena #{booking_id}', 'completed_admin_body' => '#{booking_id} — “{package_title}”: je bila označena kot zaključena.\n\nStranka: {customer_name}', 'notice_customer' => 'Datum in čas bosta dogovorjena posebej. Kmalu vas bomo kontaktirali po e-pošti ali telefonu, če je bila navedena številka.', 'notice_admin' => 'Datum ali čas nista bila izbrana. Obrnite se na stranko po e-pošti ali telefonu, če je bila navedena številka.'],
            'hr' => ['created_customer_subject' => 'Primili smo vaš zahtjev #{booking_id}', 'created_customer_body' => 'Pozdrav {customer_name},\n\nPrimili smo vaš zahtjev za “{package_title}”. Kontaktirat ćemo vas radi dogovora o detaljima, datumu i vremenu.\n\nBroj zahtjeva: #{booking_id}\n\nOtkaži zahtjev: {cancellation_url}', 'created_admin_subject' => 'Novi zahtjev za rezervaciju #{booking_id}', 'created_admin_body' => 'Primljen je novi zahtjev za rezervaciju.\n\nKlijent: {customer_name}\nE-pošta: {customer_email}\nTelefon: {customer_phone}\nUsluga: {package_title}\nBroj zahtjeva: #{booking_id}\n\nKontaktirajte klijenta radi dogovora o detaljima.', 'cancelled_customer_subject' => 'Zahtjev otkazan #{booking_id}', 'cancelled_customer_body' => 'Pozdrav {customer_name},\n\nVaš zahtjev za “{package_title}” je otkazan.\n\nBroj zahtjeva: #{booking_id}', 'cancelled_admin_subject' => 'Zahtjev otkazan #{booking_id}', 'cancelled_admin_body' => '#{booking_id} — “{package_title}”: je otkazan.\n\nKlijent: {customer_name}\nE-pošta: {customer_email}', 'completed_customer_subject' => 'Zahtjev dovršen #{booking_id}', 'completed_customer_body' => 'Pozdrav {customer_name},\n\nVaš zahtjev za “{package_title}” je označen kao dovršen.\n\nBroj zahtjeva: #{booking_id}\n\nHvala što ste odabrali nas.', 'completed_admin_subject' => 'Zahtjev dovršen #{booking_id}', 'completed_admin_body' => '#{booking_id} — “{package_title}”: je označen kao dovršen.\n\nKlijent: {customer_name}', 'notice_customer' => 'Datum i vrijeme dogovorit će se zasebno. Uskoro ćemo vas kontaktirati e-poštom ili telefonom ako je naveden broj.', 'notice_admin' => 'Datum ni vrijeme nisu odabrani. Kontaktirajte klijenta e-poštom ili telefonom ako je naveden broj.'],
            'hu_HU' => ['created_customer_subject' => 'Megkaptuk kérelmét #{booking_id}', 'created_customer_body' => 'Üdvözöljük {customer_name},\n\nMegkaptuk kérelmét erre: “{package_title}”. Kapcsolatba lépünk Önnel a részletek, a dátum és az időpont egyeztetéséhez.\n\nKérelem száma: #{booking_id}\n\nKérelem lemondása: {cancellation_url}', 'created_admin_subject' => 'Új foglalási kérelem #{booking_id}', 'created_admin_body' => 'Új foglalási kérelem érkezett.\n\nÜgyfél: {customer_name}\nE-mail: {customer_email}\nTelefon: {customer_phone}\nSzolgáltatás: {package_title}\nKérelem száma: #{booking_id}\n\nLépjen kapcsolatba az ügyféllel a részletek egyeztetéséhez.', 'cancelled_customer_subject' => 'Kérelem lemondva #{booking_id}', 'cancelled_customer_body' => 'Üdvözöljük {customer_name},\n\nAz Ön kérelme erre: “{package_title}” lemondásra került.\n\nKérelem száma: #{booking_id}', 'cancelled_admin_subject' => 'Kérelem lemondva #{booking_id}', 'cancelled_admin_body' => '#{booking_id} — “{package_title}”: lemondásra került.\n\nÜgyfél: {customer_name}\nE-mail: {customer_email}', 'completed_customer_subject' => 'Kérelem teljesítve #{booking_id}', 'completed_customer_body' => 'Üdvözöljük {customer_name},\n\nAz Ön kérelme erre: “{package_title}” teljesítettként lett megjelölve.\n\nKérelem száma: #{booking_id}\n\nKöszönjük, hogy minket választott.', 'completed_admin_subject' => 'Kérelem teljesítve #{booking_id}', 'completed_admin_body' => '#{booking_id} — “{package_title}”: teljesítettként lett megjelölve.\n\nÜgyfél: {customer_name}', 'notice_customer' => 'A dátumot és az időpontot külön egyeztetjük. Hamarosan kapcsolatba lépünk e-mailben vagy telefonon, ha megadott telefonszámot.', 'notice_admin' => 'Nem választottak dátumot vagy időpontot. Lépjen kapcsolatba az ügyféllel e-mailben vagy telefonon, ha megadott telefonszámot.'],
            'ro_RO' => ['created_customer_subject' => 'Am primit solicitarea dvs. #{booking_id}', 'created_customer_body' => 'Bună ziua {customer_name},\n\nAm primit solicitarea dvs. pentru “{package_title}”. Vă vom contacta pentru a stabili detaliile, data și ora.\n\nNumărul solicitării: #{booking_id}\n\nAnulează solicitarea: {cancellation_url}', 'created_admin_subject' => 'Solicitare nouă de rezervare #{booking_id}', 'created_admin_body' => 'A fost primită o solicitare nouă de rezervare.\n\nClient: {customer_name}\nE-mail: {customer_email}\nTelefon: {customer_phone}\nServiciu: {package_title}\nNumărul solicitării: #{booking_id}\n\nContactați clientul pentru a stabili detaliile.', 'cancelled_customer_subject' => 'Solicitare anulată #{booking_id}', 'cancelled_customer_body' => 'Bună ziua {customer_name},\n\nSolicitarea dvs. pentru “{package_title}” a fost anulată.\n\nNumărul solicitării: #{booking_id}', 'cancelled_admin_subject' => 'Solicitare anulată #{booking_id}', 'cancelled_admin_body' => '#{booking_id} — “{package_title}”: a fost anulată.\n\nClient: {customer_name}\nE-mail: {customer_email}', 'completed_customer_subject' => 'Solicitare finalizată #{booking_id}', 'completed_customer_body' => 'Bună ziua {customer_name},\n\nSolicitarea dvs. pentru “{package_title}” a fost marcată ca finalizată.\n\nNumărul solicitării: #{booking_id}\n\nVă mulțumim că ne-ați ales.', 'completed_admin_subject' => 'Solicitare finalizată #{booking_id}', 'completed_admin_body' => '#{booking_id} — “{package_title}”: a fost marcată ca finalizată.\n\nClient: {customer_name}', 'notice_customer' => 'Data și ora vor fi stabilite separat. Vă vom contacta în curând prin e-mail sau telefon dacă a fost furnizat un număr.', 'notice_admin' => 'Nu au fost selectate data și ora. Contactați clientul prin e-mail sau telefon dacă a fost furnizat un număr.'],
            'bg_BG' => ['created_customer_subject' => 'Получихме вашата заявка #{booking_id}', 'created_customer_body' => 'Здравейте {customer_name},\n\nПолучихме вашата заявка за “{package_title}”. Ще се свържем с вас, за да уточним подробностите, датата и часа.\n\nНомер на заявката: #{booking_id}\n\nОтмяна на заявката: {cancellation_url}', 'created_admin_subject' => 'Нова заявка за резервация #{booking_id}', 'created_admin_body' => 'Получена е нова заявка за резервация.\n\nКлиент: {customer_name}\nИмейл: {customer_email}\nТелефон: {customer_phone}\nУслуга: {package_title}\nНомер на заявката: #{booking_id}\n\nСвържете се с клиента, за да уточните подробностите.', 'cancelled_customer_subject' => 'Заявката е отменена #{booking_id}', 'cancelled_customer_body' => 'Здравейте {customer_name},\n\nВашата заявка за “{package_title}” е отменена.\n\nНомер на заявката: #{booking_id}', 'cancelled_admin_subject' => 'Заявката е отменена #{booking_id}', 'cancelled_admin_body' => '#{booking_id} — “{package_title}”: е отменена.\n\nКлиент: {customer_name}\nИмейл: {customer_email}', 'completed_customer_subject' => 'Заявката е завършена #{booking_id}', 'completed_customer_body' => 'Здравейте {customer_name},\n\nВашата заявка за “{package_title}” е отбелязана като завършена.\n\nНомер на заявката: #{booking_id}\n\nБлагодарим ви, че избрахте нас.', 'completed_admin_subject' => 'Заявката е завършена #{booking_id}', 'completed_admin_body' => '#{booking_id} — “{package_title}”: е отбелязана като завършена.\n\nКлиент: {customer_name}', 'notice_customer' => 'Датата и часът ще бъдат уточнени отделно. Скоро ще се свържем с вас по имейл или телефон, ако е посочен номер.', 'notice_admin' => 'Не са избрани дата и час. Свържете се с клиента по имейл или телефон, ако е посочен номер.'],
            'lt_LT' => ['created_customer_subject' => 'Gavome jūsų užklausą #{booking_id}', 'created_customer_body' => 'Sveiki {customer_name},\n\nGavome jūsų užklausą dėl “{package_title}”. Susisieksime, kad suderintume informaciją, datą ir laiką.\n\nUžklausos numeris: #{booking_id}\n\nAtšaukti užklausą: {cancellation_url}', 'created_admin_subject' => 'Nauja rezervacijos užklausa #{booking_id}', 'created_admin_body' => 'Gauta nauja rezervacijos užklausa.\n\nKlientas: {customer_name}\nEl. paštas: {customer_email}\nTelefonas: {customer_phone}\nPaslauga: {package_title}\nUžklausos numeris: #{booking_id}\n\nSusisiekite su klientu ir suderinkite informaciją.', 'cancelled_customer_subject' => 'Užklausa atšaukta #{booking_id}', 'cancelled_customer_body' => 'Sveiki {customer_name},\n\nJūsų užklausa dėl “{package_title}” buvo atšaukta.\n\nUžklausos numeris: #{booking_id}', 'cancelled_admin_subject' => 'Užklausa atšaukta #{booking_id}', 'cancelled_admin_body' => '#{booking_id} — “{package_title}”: buvo atšaukta.\n\nKlientas: {customer_name}\nEl. paštas: {customer_email}', 'completed_customer_subject' => 'Užklausa užbaigta #{booking_id}', 'completed_customer_body' => 'Sveiki {customer_name},\n\nJūsų užklausa dėl “{package_title}” pažymėta kaip užbaigta.\n\nUžklausos numeris: #{booking_id}\n\nDėkojame, kad pasirinkote mus.', 'completed_admin_subject' => 'Užklausa užbaigta #{booking_id}', 'completed_admin_body' => '#{booking_id} — “{package_title}”: pažymėta kaip užbaigta.\n\nKlientas: {customer_name}', 'notice_customer' => 'Data ir laikas bus suderinti atskirai. Netrukus susisieksime el. paštu arba telefonu, jei buvo nurodytas numeris.', 'notice_admin' => 'Data ir laikas nepasirinkti. Susisiekite su klientu el. paštu arba telefonu, jei buvo nurodytas numeris.'],
            'lv' => ['created_customer_subject' => 'Mēs saņēmām jūsu pieprasījumu #{booking_id}', 'created_customer_body' => 'Labdien {customer_name},\n\nMēs saņēmām jūsu pieprasījumu par “{package_title}”. Mēs sazināsimies, lai vienotos par detaļām, datumu un laiku.\n\nPieprasījuma numurs: #{booking_id}\n\nAtcelt pieprasījumu: {cancellation_url}', 'created_admin_subject' => 'Jauns rezervācijas pieprasījums #{booking_id}', 'created_admin_body' => 'Ir saņemts jauns rezervācijas pieprasījums.\n\nKlients: {customer_name}\nE-pasts: {customer_email}\nTālrunis: {customer_phone}\nPakalpojums: {package_title}\nPieprasījuma numurs: #{booking_id}\n\nSazinieties ar klientu, lai vienotos par detaļām.', 'cancelled_customer_subject' => 'Pieprasījums atcelts #{booking_id}', 'cancelled_customer_body' => 'Labdien {customer_name},\n\nJūsu pieprasījums par “{package_title}” ir atcelts.\n\nPieprasījuma numurs: #{booking_id}', 'cancelled_admin_subject' => 'Pieprasījums atcelts #{booking_id}', 'cancelled_admin_body' => '#{booking_id} — “{package_title}”: ir atcelts.\n\nKlients: {customer_name}\nE-pasts: {customer_email}', 'completed_customer_subject' => 'Pieprasījums pabeigts #{booking_id}', 'completed_customer_body' => 'Labdien {customer_name},\n\nJūsu pieprasījums par “{package_title}” ir atzīmēts kā pabeigts.\n\nPieprasījuma numurs: #{booking_id}\n\nPaldies, ka izvēlējāties mūs.', 'completed_admin_subject' => 'Pieprasījums pabeigts #{booking_id}', 'completed_admin_body' => '#{booking_id} — “{package_title}”: ir atzīmēts kā pabeigts.\n\nKlients: {customer_name}', 'notice_customer' => 'Datums un laiks tiks saskaņoti atsevišķi. Drīzumā sazināsimies pa e-pastu vai tālruni, ja tika norādīts numurs.', 'notice_admin' => 'Datums un laiks netika izvēlēti. Sazinieties ar klientu pa e-pastu vai tālruni, ja tika norādīts numurs.'],
            'sv_SE' => ['created_customer_subject' => 'Vi har tagit emot din förfrågan #{booking_id}', 'created_customer_body' => 'Hej {customer_name},\n\nVi har tagit emot din förfrågan om “{package_title}”. Vi kontaktar dig för att komma överens om detaljer, datum och tid.\n\nFörfrågningsnummer: #{booking_id}\n\nAvbryt förfrågan: {cancellation_url}', 'created_admin_subject' => 'Ny bokningsförfrågan #{booking_id}', 'created_admin_body' => 'En ny bokningsförfrågan har tagits emot.\n\nKund: {customer_name}\nE-post: {customer_email}\nTelefon: {customer_phone}\nTjänst: {package_title}\nFörfrågningsnummer: #{booking_id}\n\nKontakta kunden för att komma överens om detaljerna.', 'cancelled_customer_subject' => 'Förfrågan avbruten #{booking_id}', 'cancelled_customer_body' => 'Hej {customer_name},\n\nDin förfrågan om “{package_title}” har avbrutits.\n\nFörfrågningsnummer: #{booking_id}', 'cancelled_admin_subject' => 'Förfrågan avbruten #{booking_id}', 'cancelled_admin_body' => '#{booking_id} — “{package_title}”: har avbrutits.\n\nKund: {customer_name}\nE-post: {customer_email}', 'completed_customer_subject' => 'Förfrågan slutförd #{booking_id}', 'completed_customer_body' => 'Hej {customer_name},\n\nDin förfrågan om “{package_title}” har markerats som slutförd.\n\nFörfrågningsnummer: #{booking_id}\n\nTack för att du valde oss.', 'completed_admin_subject' => 'Förfrågan slutförd #{booking_id}', 'completed_admin_body' => '#{booking_id} — “{package_title}”: har markerats som slutförd.\n\nKund: {customer_name}', 'notice_customer' => 'Datum och tid bestäms separat. Vi kontaktar dig snart via e-post eller telefon om ett nummer angavs.', 'notice_admin' => 'Inget datum eller klockslag valdes. Kontakta kunden via e-post eller telefon om ett nummer angavs.'],
            'da_DK' => ['created_customer_subject' => 'Vi har modtaget din anmodning #{booking_id}', 'created_customer_body' => 'Hej {customer_name},\n\nVi har modtaget din anmodning om “{package_title}”. Vi kontakter dig for at aftale detaljer, dato og tidspunkt.\n\nAnmodningsnummer: #{booking_id}\n\nAnnuller anmodning: {cancellation_url}', 'created_admin_subject' => 'Ny bookinganmodning #{booking_id}', 'created_admin_body' => 'Der er modtaget en ny bookinganmodning.\n\nKunde: {customer_name}\nE-mail: {customer_email}\nTelefon: {customer_phone}\nYdelse: {package_title}\nAnmodningsnummer: #{booking_id}\n\nKontakt kunden for at aftale detaljerne.', 'cancelled_customer_subject' => 'Anmodning annulleret #{booking_id}', 'cancelled_customer_body' => 'Hej {customer_name},\n\nDin anmodning om “{package_title}” er blevet annulleret.\n\nAnmodningsnummer: #{booking_id}', 'cancelled_admin_subject' => 'Anmodning annulleret #{booking_id}', 'cancelled_admin_body' => '#{booking_id} — “{package_title}”: er blevet annulleret.\n\nKunde: {customer_name}\nE-mail: {customer_email}', 'completed_customer_subject' => 'Anmodning gennemført #{booking_id}', 'completed_customer_body' => 'Hej {customer_name},\n\nDin anmodning om “{package_title}” er markeret som gennemført.\n\nAnmodningsnummer: #{booking_id}\n\nTak fordi du valgte os.', 'completed_admin_subject' => 'Anmodning gennemført #{booking_id}', 'completed_admin_body' => '#{booking_id} — “{package_title}”: er markeret som gennemført.\n\nKunde: {customer_name}', 'notice_customer' => 'Dato og tidspunkt aftales separat. Vi kontakter dig snart via e-mail eller telefon, hvis et nummer blev angivet.', 'notice_admin' => 'Der er ikke valgt dato eller tidspunkt. Kontakt kunden via e-mail eller telefon, hvis et nummer blev angivet.'],
            'fi' => ['created_customer_subject' => 'Olemme vastaanottaneet pyyntösi #{booking_id}', 'created_customer_body' => 'Hei {customer_name},\n\nOlemme vastaanottaneet pyyntösi kohteesta “{package_title}”. Otamme yhteyttä sopiaksemme yksityiskohdista, päivämäärästä ja ajasta.\n\nPyynnön numero: #{booking_id}\n\nPeruuta pyyntö: {cancellation_url}', 'created_admin_subject' => 'Uusi varauspyyntö #{booking_id}', 'created_admin_body' => 'Uusi varauspyyntö on vastaanotettu.\n\nAsiakas: {customer_name}\nSähköposti: {customer_email}\nPuhelin: {customer_phone}\nPalvelu: {package_title}\nPyynnön numero: #{booking_id}\n\nOta yhteyttä asiakkaaseen sopiaksesi yksityiskohdista.', 'cancelled_customer_subject' => 'Pyyntö peruutettu #{booking_id}', 'cancelled_customer_body' => 'Hei {customer_name},\n\nPyyntösi kohteesta “{package_title}” on peruutettu.\n\nPyynnön numero: #{booking_id}', 'cancelled_admin_subject' => 'Pyyntö peruutettu #{booking_id}', 'cancelled_admin_body' => '#{booking_id} — “{package_title}”: on peruutettu.\n\nAsiakas: {customer_name}\nSähköposti: {customer_email}', 'completed_customer_subject' => 'Pyyntö valmis #{booking_id}', 'completed_customer_body' => 'Hei {customer_name},\n\nPyyntösi kohteesta “{package_title}” on merkitty valmiiksi.\n\nPyynnön numero: #{booking_id}\n\nKiitos, että valitsit meidät.', 'completed_admin_subject' => 'Pyyntö valmis #{booking_id}', 'completed_admin_body' => '#{booking_id} — “{package_title}”: on merkitty valmiiksi.\n\nAsiakas: {customer_name}', 'notice_customer' => 'Päivämäärä ja aika sovitaan erikseen. Otamme pian yhteyttä sähköpostitse tai puhelimitse, jos numero annettiin.', 'notice_admin' => 'Päivämäärää tai aikaa ei valittu. Ota yhteyttä asiakkaaseen sähköpostitse tai puhelimitse, jos numero annettiin.'],
            'no_NO' => ['created_customer_subject' => 'Vi har mottatt forespørselen din #{booking_id}', 'created_customer_body' => 'Hei {customer_name},\n\nVi har mottatt forespørselen din om “{package_title}”. Vi kontakter deg for å avtale detaljer, dato og tidspunkt.\n\nForespørselsnummer: #{booking_id}\n\nAvbryt forespørsel: {cancellation_url}', 'created_admin_subject' => 'Ny bestillingsforespørsel #{booking_id}', 'created_admin_body' => 'En ny bestillingsforespørsel er mottatt.\n\nKunde: {customer_name}\nE-post: {customer_email}\nTelefon: {customer_phone}\nTjeneste: {package_title}\nForespørselsnummer: #{booking_id}\n\nKontakt kunden for å avtale detaljene.', 'cancelled_customer_subject' => 'Forespørsel avbrutt #{booking_id}', 'cancelled_customer_body' => 'Hei {customer_name},\n\nForespørselen din om “{package_title}” er avbrutt.\n\nForespørselsnummer: #{booking_id}', 'cancelled_admin_subject' => 'Forespørsel avbrutt #{booking_id}', 'cancelled_admin_body' => '#{booking_id} — “{package_title}”: er avbrutt.\n\nKunde: {customer_name}\nE-post: {customer_email}', 'completed_customer_subject' => 'Forespørsel fullført #{booking_id}', 'completed_customer_body' => 'Hei {customer_name},\n\nForespørselen din om “{package_title}” er merket som fullført.\n\nForespørselsnummer: #{booking_id}\n\nTakk for at du valgte oss.', 'completed_admin_subject' => 'Forespørsel fullført #{booking_id}', 'completed_admin_body' => '#{booking_id} — “{package_title}”: er merket som fullført.\n\nKunde: {customer_name}', 'notice_customer' => 'Dato og tidspunkt avtales separat. Vi kontakter deg snart via e-post eller telefon hvis et nummer ble oppgitt.', 'notice_admin' => 'Ingen dato eller tidspunkt ble valgt. Kontakt kunden via e-post eller telefon hvis et nummer ble oppgitt.'],
            'is_IS' => ['created_customer_subject' => 'Við höfum móttekið beiðnina þína #{booking_id}', 'created_customer_body' => 'Halló {customer_name},\n\nVið höfum móttekið beiðnina þína um “{package_title}”. Við höfum samband til að semja um nánari upplýsingar, dagsetningu og tíma.\n\nBeiðninúmer: #{booking_id}\n\nHætta við beiðni: {cancellation_url}', 'created_admin_subject' => 'Ný bókunarbeiðni #{booking_id}', 'created_admin_body' => 'Ný bókunarbeiðni barst.\n\nViðskiptavinur: {customer_name}\nNetfang: {customer_email}\nSími: {customer_phone}\nÞjónusta: {package_title}\nBeiðninúmer: #{booking_id}\n\nHafðu samband við viðskiptavininn til að semja um nánari upplýsingar.', 'cancelled_customer_subject' => 'Beiðni afturkölluð #{booking_id}', 'cancelled_customer_body' => 'Halló {customer_name},\n\nBeiðnin þín um “{package_title}” hefur verið afturkölluð.\n\nBeiðninúmer: #{booking_id}', 'cancelled_admin_subject' => 'Beiðni afturkölluð #{booking_id}', 'cancelled_admin_body' => '#{booking_id} — “{package_title}”: hefur verið afturkölluð.\n\nViðskiptavinur: {customer_name}\nNetfang: {customer_email}', 'completed_customer_subject' => 'Beiðni lokið #{booking_id}', 'completed_customer_body' => 'Halló {customer_name},\n\nBeiðnin þín um “{package_title}” hefur verið merkt lokið.\n\nBeiðninúmer: #{booking_id}\n\nTakk fyrir að velja okkur.', 'completed_admin_subject' => 'Beiðni lokið #{booking_id}', 'completed_admin_body' => '#{booking_id} — “{package_title}”: hefur verið merkt lokið.\n\nViðskiptavinur: {customer_name}', 'notice_customer' => 'Dagsetning og tími verða ákveðin sérstaklega. Við höfum fljótlega samband með tölvupósti eða síma ef númer var gefið upp.', 'notice_admin' => 'Engin dagsetning eða tími var valinn. Hafðu samband við viðskiptavininn með tölvupósti eða síma ef númer var gefið upp.'],
            'el' => ['created_customer_subject' => 'Λάβαμε το αίτημά σας #{booking_id}', 'created_customer_body' => 'Γεια σας {customer_name},\n\nΛάβαμε το αίτημά σας για “{package_title}”. Θα επικοινωνήσουμε για να συμφωνήσουμε τις λεπτομέρειες, την ημερομηνία και την ώρα.\n\nΑριθμός αιτήματος: #{booking_id}\n\nΑκύρωση αιτήματος: {cancellation_url}', 'created_admin_subject' => 'Νέο αίτημα κράτησης #{booking_id}', 'created_admin_body' => 'Λήφθηκε νέο αίτημα κράτησης.\n\nΠελάτης: {customer_name}\nEmail: {customer_email}\nΤηλέφωνο: {customer_phone}\nΥπηρεσία: {package_title}\nΑριθμός αιτήματος: #{booking_id}\n\nΕπικοινωνήστε με τον πελάτη για να συμφωνήσετε τις λεπτομέρειες.', 'cancelled_customer_subject' => 'Το αίτημα ακυρώθηκε #{booking_id}', 'cancelled_customer_body' => 'Γεια σας {customer_name},\n\nΤο αίτημά σας για “{package_title}” ακυρώθηκε.\n\nΑριθμός αιτήματος: #{booking_id}', 'cancelled_admin_subject' => 'Το αίτημα ακυρώθηκε #{booking_id}', 'cancelled_admin_body' => '#{booking_id} — “{package_title}”: ακυρώθηκε.\n\nΠελάτης: {customer_name}\nEmail: {customer_email}', 'completed_customer_subject' => 'Το αίτημα ολοκληρώθηκε #{booking_id}', 'completed_customer_body' => 'Γεια σας {customer_name},\n\nΤο αίτημά σας για “{package_title}” σημειώθηκε ως ολοκληρωμένο.\n\nΑριθμός αιτήματος: #{booking_id}\n\nΣας ευχαριστούμε που μας επιλέξατε.', 'completed_admin_subject' => 'Το αίτημα ολοκληρώθηκε #{booking_id}', 'completed_admin_body' => '#{booking_id} — “{package_title}”: σημειώθηκε ως ολοκληρωμένο.\n\nΠελάτης: {customer_name}', 'notice_customer' => 'Η ημερομηνία και η ώρα θα συμφωνηθούν ξεχωριστά. Θα επικοινωνήσουμε σύντομα μέσω email ή τηλεφώνου, εάν δόθηκε αριθμός.', 'notice_admin' => 'Δεν επιλέχθηκε ημερομηνία ή ώρα. Επικοινωνήστε με τον πελάτη μέσω email ή τηλεφώνου, εάν δόθηκε αριθμός.'],
